-- ============================================================
-- Quiz coverage for Phase 3 batch 4 (GCP -- first GCP batch):
-- cloud/gke, cloud/bigquery, cloud/cloud-run.
-- 5 questions each for overview, fundamentals, intermediate,
-- advanced -- the four tabs with real, substantive live content
-- for all three technologies in this batch.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- cloud/gke/overview ----------
('cloud', 'gke', 'overview', 'What is the fundamental billing difference between GKE Standard and GKE Autopilot?', '["They are billed identically", "Standard bills per node whether or not pods are running on it; Autopilot bills per Pod CPU/memory resource request", "Autopilot is always more expensive regardless of workload", "Standard only exists for legacy accounts"]', 1, 'Standard mode gives you full control over node pools but you pay for provisioned nodes even when idle. Autopilot removes node management entirely and bills based on what each Pod actually requests.', 'beginner'),
('cloud', 'gke', 'overview', 'In GKE, what problem does Workload Identity solve?', '["It speeds up cluster autoscaling", "It lets a Pod authenticate as a real GCP service account without ever storing a downloaded service-account key file in the container or cluster", "It replaces the need for a Kubernetes ServiceAccount entirely", "It is only used for billing attribution"]', 1, 'Workload Identity binds a Kubernetes ServiceAccount to a GCP IAM service account via impersonation through the metadata server, eliminating the security risk of long-lived downloaded key files inside containers.', 'intermediate'),
('cloud', 'gke', 'overview', 'On a regional GKE Standard cluster, what does the --num-nodes flag actually control?', '["The total node count across the whole cluster", "The node count PER ZONE -- a regional cluster spanning 3 zones with --num-nodes 3 provisions 9 VMs total, not 3", "The maximum number of Pods per node", "It has no effect on regional clusters"]', 1, 'This is a very common sizing mistake for people new to GKE regional clusters -- the flag is per-zone, so total node count is num-nodes multiplied by the number of zones the cluster spans.', 'intermediate'),
('cloud', 'gke', 'overview', 'Who actually manages and patches the Kubernetes control plane (api-server, etcd, scheduler) on GKE?', '["The customer, in both Standard and Autopilot mode", "Google manages the control plane in BOTH Standard and Autopilot mode -- the difference between the two modes is about who manages the worker NODES, not the control plane", "Google only manages it in Autopilot mode", "There is no control plane on GKE -- it is fully serverless"]', 1, 'This is a common point of confusion: even GKE Standard, where you manage node pools yourself, still has a fully Google-managed control plane. Autopilot additionally takes node management off your hands.', 'beginner'),
('cloud', 'gke', 'overview', 'Why is GKE Standard generally preferred over Autopilot for GPU-heavy ML training workloads with unusual hardware requirements?', '["Autopilot cannot run GPU workloads under any circumstances", "Standard gives full control over machine types, node taints, and custom node pool configuration, which matters for highly specific hardware/driver requirements that go beyond what Autopilot''s more constrained node provisioning supports", "GPUs are billed identically on both modes so there is no reason to prefer either", "Autopilot clusters cannot be created in regions with GPU availability"]', 1, 'Autopilot does support GPUs through Pod-level accelerator requests, but Standard''s full control over node pool configuration is generally the better fit when workloads need very specific, custom hardware setups.', 'advanced'),

-- ---------- cloud/gke/fundamentals ----------
('cloud', 'gke', 'fundamentals', 'What does annotating a Kubernetes ServiceAccount with iam.gke.io/gcp-service-account actually do, by itself, before any IAM binding is granted?', '["It immediately grants the Pod every permission the named GCP service account has", "It only links the two identities together -- no permissions flow until a separate roles/iam.workloadIdentityUser binding AND actual GCP resource permissions are granted to the GCP service account", "It deletes the Kubernetes ServiceAccount and replaces it with the GCP one", "It is purely cosmetic and has no functional effect at all"]', 1, 'Workload Identity setup is intentionally composed of separate steps: annotate (link identities), bind (allow impersonation), and grant (actual GCP permissions) -- understanding they are independent is key to debugging "why can''t my Pod reach GCS" issues.', 'intermediate'),
('cloud', 'gke', 'fundamentals', 'What is the correct way to enable the Vertical Pod Autoscaler on a GKE cluster?', '["Manually apply the open-source kubernetes/autoscaler project''s YAML with kubectl apply -f", "Update the GKE cluster with the built-in --enable-vertical-pod-autoscaling flag, since GKE ships VPA as a native cluster feature rather than requiring manual installation of the upstream OSS project", "VPA cannot be used on GKE at all, only HPA", "VPA is enabled by default on every new cluster and cannot be disabled"]', 1, 'GKE integrates VPA as a first-class managed feature -- gcloud container clusters update --enable-vertical-pod-autoscaling -- rather than requiring you to install and maintain the community project yourself.', 'intermediate'),
('cloud', 'gke', 'fundamentals', 'What does --enable-ip-alias configure when creating a GKE cluster?', '["It enables a CDN in front of the cluster", "It creates a VPC-native cluster where Pods get real, routable IP addresses from the VPC''s secondary ranges, rather than relying on node-level NAT/routing overhead", "It is a deprecated flag with no current effect", "It restricts the cluster to a single availability zone"]', 1, 'VPC-native (alias IP) clusters are the modern default and are required for private clusters and several networking features -- Pods become directly addressable within the VPC instead of hidden behind node-level routing.', 'intermediate'),
('cloud', 'gke', 'fundamentals', 'What is the purpose of the Cloud SQL Auth Proxy pattern when a GKE workload needs to reach a Cloud SQL database?', '["It replaces the database entirely with an in-cluster cache", "It runs as a sidecar container that authenticates to Cloud SQL using the Pod''s identity (via Workload Identity), avoiding both a public database IP and stored database passwords/firewall rules", "It is required only for MySQL, never for PostgreSQL", "It automatically backs up the database on a schedule"]', 1, 'The sidecar handles encrypted, IAM-authenticated connections to Cloud SQL without exposing a public IP or managing static credentials/firewall rules -- Workload Identity is what lets it authenticate without a key file.', 'advanced'),
('cloud', 'gke', 'fundamentals', 'When creating a GPU node pool with --machine-type a2-highgpu-1g and --accelerator type=nvidia-tesla-a100,count=1, what should you know about A2 machine types?', '["A2 machine types cannot be used with GKE, only Compute Engine VMs", "A2 machine types have GPUs baked into the machine type name itself, and whether the --accelerator flag is still required or redundant alongside them has changed across gcloud versions -- worth checking current CLI docs before assuming both are always needed", "A100 GPUs are only available on N2 machine types, not A2", "The --accelerator flag is used exclusively for TPUs, never GPUs"]', 1, 'This is a case where the exact current CLI requirement is worth verifying directly rather than assuming, since A2''s GPU configuration is already implied by the machine type name.', 'advanced'),

-- ---------- cloud/gke/intermediate ----------
('cloud', 'gke', 'intermediate', 'In GKE Autopilot, what happens to billing when a Pod is idle but still scheduled (not scaled down)?', '["Nothing is billed until the Pod actually receives traffic", "You are billed for the Pod''s resource requests (CPU/memory) as long as it is running, regardless of whether it is actively handling traffic -- Autopilot bills per running Pod resource request, not per request served", "Billing pauses automatically after 5 minutes of inactivity", "Autopilot Pods are always free unless they exceed a quota"]', 1, 'This is a key distinction from something like Cloud Run: Autopilot removes node management, but a Pod that is up and running is still billed for its resource requests, whether or not it is currently serving requests.', 'intermediate'),
('cloud', 'gke', 'intermediate', 'What is the difference between GKE''s Cluster Autoscaler and Node Auto-provisioning?', '["They are the same feature under two different names", "Cluster Autoscaler resizes EXISTING node pools up or down based on pending pods; Node Auto-provisioning (Standard mode only) creates entirely NEW node pools sized to match pending pods'' requirements", "Node Auto-provisioning is available in Autopilot only", "Cluster Autoscaler only works with Spot VMs"]', 1, 'Cluster Autoscaler works within the node pools you already have; Node Auto-provisioning goes a step further and creates new pools automatically when nothing existing fits the pending workload.', 'advanced'),
('cloud', 'gke', 'intermediate', 'What does registering a cluster to a GKE Fleet with --enable-workload-identity enable for multi-cluster management?', '["It merges multiple clusters into a single control plane", "It enrolls the cluster for fleet-level features like Config Sync (GitOps across clusters) and multi-cluster Gateway/Services, while keeping Workload Identity as the auth mechanism across the fleet", "It automatically migrates all workloads to Autopilot", "Fleet membership has no functional effect, it is purely for billing grouping"]', 1, 'Fleet membership is the prerequisite for GKE''s multi-cluster features (Config Sync, multi-cluster ingress/services, Policy Controller, Service Mesh) -- each cluster keeps its own control plane, but they become manageable as a group.', 'advanced'),
('cloud', 'gke', 'intermediate', 'Why does GKE Autopilot enforce that every Pod must declare resource requests?', '["It is an arbitrary restriction with no functional purpose", "Since Autopilot bills per Pod resource request rather than per node, an unset request would make billing (and scheduling/bin-packing) undefined -- Autopilot needs the request to know what to bill for and how to place the Pod", "Resource requests are only needed for Horizontal Pod Autoscaler to function", "This restriction only applies to Deployments, not to bare Pods"]', 1, 'Because the entire Autopilot billing model is built around Pod resource requests, Autopilot cannot function correctly (billing or scheduling) without every Pod declaring them -- unlike Standard mode where requests are best-practice but optional.', 'intermediate'),
('cloud', 'gke', 'intermediate', 'What is the practical benefit of Spot VMs in a GKE node pool, and what is the tradeoff?', '["They are cheaper with no tradeoff whatsoever", "They are significantly cheaper than standard on-demand nodes, but can be reclaimed/evicted by Google with short notice, making them suitable only for fault-tolerant, interruption-tolerant workloads like batch jobs, not stateful primary replicas", "They provide guaranteed uptime SLAs identical to standard nodes", "Spot VMs can only be used in Autopilot mode"]', 1, 'The cost savings come with the explicit tradeoff that Google can reclaim the underlying VM at short notice -- appropriate for batch processing, CI runners, or workloads with graceful rescheduling, not for anything requiring guaranteed availability.', 'intermediate'),

-- ---------- cloud/gke/advanced ----------
('cloud', 'gke', 'advanced', 'What is the key architectural difference between --enable-network-policy (Calico) and --enable-dataplane-v2 (Cilium) on GKE?', '["They are two names for the exact same underlying implementation", "Both provide Kubernetes NetworkPolicy enforcement, but Dataplane V2 (Cilium-based, eBPF) is GKE''s newer default dataplane that includes network policy support built in, rather than layering Calico on top as a separate component", "Calico only works on Autopilot, Dataplane V2 only works on Standard", "Network policies are not supported by either option on GKE"]', 1, 'Dataplane V2 replaces the traditional iptables-based networking with an eBPF-based Cilium dataplane, which includes NetworkPolicy enforcement as part of the dataplane itself rather than a bolted-on Calico component.', 'advanced'),
('cloud', 'gke', 'advanced', 'What does --enable-private-nodes combined with --enable-private-endpoint achieve on a GKE cluster?', '["Only the nodes are private; the control plane remains fully public", "Both the worker nodes AND the cluster''s control plane API endpoint become inaccessible from the public internet -- nodes get no public IPs, and even kubectl access to the control plane requires being on an authorized network or using Private Service Connect", "It disables all outbound internet access for the cluster with no way to re-enable it", "It automatically enables Binary Authorization as a side effect"]', 1, '--enable-private-nodes removes public IPs from worker nodes; --enable-private-endpoint additionally makes the control plane itself reachable only from private/authorized networks rather than the public internet.', 'advanced'),
('cloud', 'gke', 'advanced', 'What is the purpose of Binary Authorization on GKE?', '["It authorizes billing changes to the GCP project", "It enforces that only container images which have valid attestations (e.g. signed off by a CI/CD pipeline) can be deployed to the cluster, blocking unverified/untrusted images at admission time", "It is a network firewall rule set, unrelated to container images", "It replaces Workload Identity for pod authentication"]', 1, 'Binary Authorization is a deploy-time policy control -- it checks that an image has the required attestations before allowing it onto the cluster, which is a supply-chain security control, not a networking or identity feature.', 'advanced'),
('cloud', 'gke', 'advanced', 'In GKE Autopilot, which of these is an accurate restriction compared to Standard mode?', '["Autopilot allows privileged containers by default for faster debugging", "Autopilot disallows privileged containers and restricts most hostPath volume usage as part of its enforced security posture, and does not provide SSH access to nodes since nodes are fully Google-managed", "Autopilot has no restrictions at all -- it behaves identically to Standard", "Autopilot requires manual OS patching by the customer, unlike Standard"]', 1, 'Autopilot trades some flexibility (no privileged containers, limited hostPath, no node SSH) for automatic security hardening and zero node management -- these restrictions are a deliberate part of its security model, not limitations to work around.', 'advanced'),
('cloud', 'gke', 'advanced', 'Why would a team choose GKE Fleet''s Config Sync feature over manually applying manifests to each cluster?', '["Config Sync is required before any cluster can join a Fleet", "Config Sync implements GitOps across multiple clusters -- a Git repo becomes the single source of truth, and each fleet member cluster continuously reconciles its state to match it, rather than someone manually running kubectl apply against each cluster separately", "Config Sync only works for single-cluster deployments", "It replaces the need for a CI/CD pipeline entirely"]', 1, 'Config Sync is GKE''s managed GitOps mechanism for fleets -- it keeps multiple clusters continuously reconciled against a Git source of truth instead of relying on manual, cluster-by-cluster manifest application.', 'advanced'),

-- ---------- cloud/bigquery/overview ----------
('cloud', 'bigquery', 'overview', 'What is the core architectural difference between BigQuery and a traditional data warehouse cluster you provision yourself?', '["BigQuery requires you to size and provision a cluster upfront just like traditional warehouses", "BigQuery separates storage and compute entirely -- there is no cluster to provision; Google allocates however many workers a specific query needs on demand and tears them down afterward, billing per query rather than per idle cluster-hour", "BigQuery only supports NoSQL-style access, not SQL", "Traditional data warehouses are always cheaper for any workload size"]', 1, 'The serverless model means you never pay for idle capacity the way you do with a self-managed cluster sized for peak load -- BigQuery''s Dremel-based engine allocates compute per query.', 'beginner'),
('cloud', 'bigquery', 'overview', 'Why does partitioning a BigQuery table by date typically reduce query cost?', '["Partitioning compresses the data further, reducing storage cost only, not query cost", "A query that filters on the partition column only needs to scan the specific partition(s) matching the filter, instead of the entire table -- since BigQuery bills based on bytes scanned, this directly reduces cost", "Partitioning changes the SQL dialect required to query the table", "Partitioned tables are always stored in a cheaper storage class automatically"]', 1, 'This is "partition pruning" -- BigQuery skips reading partitions that cannot match the WHERE clause, and since on-demand billing is based on bytes scanned, less data read means lower cost.', 'beginner'),
('cloud', 'bigquery', 'overview', 'Why is SELECT * generally discouraged in BigQuery even for exploratory queries on a huge table?', '["It is a syntax error in BigQuery''s SQL dialect", "BigQuery uses columnar storage, so a query only needs to read the specific columns referenced -- SELECT * forces a scan of every column, increasing bytes scanned (and cost) far beyond selecting only the needed columns", "SELECT * disables partition pruning entirely regardless of the WHERE clause", "SELECT * is only a performance concern for row-based databases, not BigQuery"]', 1, 'Because storage is columnar, the amount of data BigQuery has to read scales with how many columns you select, not how many rows -- selecting only needed columns is one of the highest-impact, easiest optimizations.', 'intermediate'),
('cloud', 'bigquery', 'overview', 'What does require_partition_filter = true do when set on a partitioned table?', '["It automatically adds today''s date as a filter to every query", "It causes BigQuery to reject any query against that table that does not include a filter on the partition column, preventing an accidental full-table scan", "It restricts the table to only ever storing a single partition''s worth of data", "It disables clustering on the same table"]', 1, 'This is a safety/cost-control mechanism -- without it, a forgotten WHERE clause silently scans (and bills for) the entire table''s history instead of erroring out.', 'intermediate'),
('cloud', 'bigquery', 'overview', 'What is BigQuery ML''s key advantage over a typical ML workflow that exports data to a separate training environment?', '["It only supports unsupervised learning models", "Models are trained and used for prediction directly with SQL (CREATE MODEL ... AS SELECT, then ML.PREDICT), without exporting the training data out of BigQuery to a separate ML platform first", "It requires the data to first be moved into Cloud Storage as CSV before training", "BigQuery ML models cannot be evaluated, only used for prediction"]', 1, 'The "no data movement" pitch is real: CREATE MODEL trains directly against a BigQuery table using SQL syntax, and ML.PREDICT runs inference the same way, keeping the whole workflow inside BigQuery.', 'intermediate'),

-- ---------- cloud/bigquery/fundamentals ----------
('cloud', 'bigquery', 'fundamentals', 'In BigQuery SQL, what does UNNEST(items) AS item do when querying a table with a repeated/nested field called items?', '["It deletes the items field from the result set", "It flattens the repeated field into one row per element, so a single order row with 3 items becomes 3 output rows, each with one item''s fields alongside the order''s other columns", "It aggregates all items into a single JSON string column", "It is only valid in BigQuery''s legacy SQL dialect, not standard SQL"]', 1, 'UNNEST is BigQuery''s mechanism for working with its native nested/repeated (ARRAY/STRUCT) columns -- it turns array elements into individual rows you can filter, join, or aggregate normally.', 'intermediate'),
('cloud', 'bigquery', 'fundamentals', 'What is the practical difference between APPROX_COUNT_DISTINCT(x) and COUNT(DISTINCT x) on a very large table?', '["They always return identical results with no performance difference", "APPROX_COUNT_DISTINCT trades a small amount of accuracy (a small statistical error rate) for significantly faster execution on large datasets, while COUNT(DISTINCT x) is exact but more expensive to compute at scale", "COUNT(DISTINCT x) is deprecated and no longer works in BigQuery", "APPROX_COUNT_DISTINCT can only be used with integer columns"]', 1, 'This is a classic analytics tradeoff BigQuery makes easy to opt into -- when an approximate answer is acceptable (most dashboard-style use cases), APPROX_COUNT_DISTINCT is meaningfully cheaper and faster than an exact DISTINCT count over huge tables.', 'intermediate'),
('cloud', 'bigquery', 'fundamentals', 'What does the bq load command with --autodetect do when loading a CSV from Cloud Storage?', '["It automatically deletes the source file after loading", "It infers the table''s schema (column names and types) from the CSV data itself, instead of requiring you to hand-write a schema definition", "It automatically partitions the resulting table by the first column", "It converts the CSV to Parquet format before loading"]', 1, '--autodetect lets BigQuery infer column names and types from the source file, which is convenient for quick loads though hand-specifying a schema is generally safer for production pipelines where type inference could guess wrong.', 'beginner'),
('cloud', 'bigquery', 'fundamentals', 'When streaming rows into BigQuery with insert_rows_json (the Python client), how quickly does the inserted data typically become queryable?', '["It requires a manual batch job to be triggered before it becomes visible", "Streaming inserts are designed to make data available for querying in near real time, which is the main reason to choose streaming over a batch bq load job", "Streamed rows are never queryable, only usable for exports", "It becomes queryable only after 24 hours by design"]', 1, 'The whole point of streaming inserts versus batch loading is near-real-time availability for querying -- batch loads are typically free but not immediate, while streaming trades some cost for speed.', 'intermediate'),
('cloud', 'bigquery', 'fundamentals', 'What is the relationship between partitioning and clustering when both are applied to the same BigQuery table?', '["They are mutually exclusive -- a table can have one or the other, never both", "Partitioning divides the table into separate physical segments (commonly by date); clustering then sorts/groups the data WITHIN each partition by the clustering columns, so a query benefits from both partition pruning and further scan reduction within the matched partition", "Clustering must be configured before partitioning or the table creation fails", "Clustering only affects storage cost, never query performance"]', 1, 'Partitioning and clustering are complementary and commonly used together -- partition pruning eliminates whole partitions, and clustering within the remaining partition further narrows what needs to be read for a given filter.', 'advanced'),

-- ---------- cloud/bigquery/intermediate ----------
('cloud', 'bigquery', 'intermediate', 'What is an Authorized View in BigQuery used for?', '["Speeding up query execution through pre-computed caching", "Sharing query results (a view''s output) with a group of users without granting them direct access to the underlying raw table -- e.g. a view filtered to one region''s data, shared with that region''s team", "Automatically encrypting all columns in a table", "Creating a materialized, auto-refreshing copy of a table"]', 1, 'Authorized views let you grant access to a filtered/transformed slice of data (the view) while keeping the underlying base table locked down from the same users -- a row/column-level access pattern.', 'intermediate'),
('cloud', 'bigquery', 'intermediate', 'What does a BigQuery Row Access Policy (CREATE ROW ACCESS POLICY ... FILTER USING (...)) do differently from an Authorized View?', '["Nothing -- they are two syntaxes for identical functionality with no difference", "A row access policy applies the filter directly on the base table itself for specified users/groups, rather than requiring a separate view object that only shows filtered data -- both achieve row-level security but via different mechanisms", "Row access policies only work on external tables, never native BigQuery tables", "Row access policies can only restrict access by date, never by other columns"]', 1, 'Row-level security policies attach filtering logic directly to the table for specific principals, an alternative to the authorized-view pattern for restricting which rows different users can see.', 'advanced'),
('cloud', 'bigquery', 'intermediate', 'In a CREATE MODEL statement for BigQuery ML with data_split_method=''AUTO_SPLIT'', what is BigQuery doing?', '["Splitting the output table into multiple physical shards for performance", "Automatically dividing the input training data into training and evaluation subsets for you, instead of requiring you to manually partition your data with a WHERE clause split column", "Splitting the model into an ensemble of multiple sub-models", "This option only applies to unsupervised clustering models"]', 1, 'AUTO_SPLIT (or other split method options) controls how BigQuery ML partitions your input data between training and held-out evaluation data during CREATE MODEL, as an alternative to manually filtering a split column yourself.', 'intermediate'),
('cloud', 'bigquery', 'intermediate', 'Which columns are generally the best candidates for CLUSTER BY on a large fact table?', '["Low-cardinality columns like a boolean flag, since fewer distinct values group more tightly", "Columns that are both frequently used in WHERE/GROUP BY filters AND have meaningfully high cardinality, since clustering sorts data by these columns to let BigQuery skip blocks that cannot match a given filter", "Columns should be chosen at random since clustering benefit does not depend on query patterns", "Only the partitioning column itself can be reused as a clustering column"]', 1, 'Clustering is most effective on columns that queries actually filter or group by and that have enough distinct values to meaningfully narrow which storage blocks BigQuery needs to read.', 'advanced'),
('cloud', 'bigquery', 'intermediate', 'What is the practical benefit of ML.EVALUATE after training a BigQuery ML model with CREATE MODEL?', '["It retrains the model with different hyperparameters automatically", "It returns standard evaluation metrics (e.g. precision, recall, ROC AUC for classification) computed against the held-out evaluation data, letting you judge model quality before using it for real predictions", "It deletes the model if performance is below a threshold", "It converts the model to a different model_type"]', 1, 'ML.EVALUATE is the standard way to check whether a freshly trained BigQuery ML model is actually any good before relying on ML.PREDICT for real decisions.', 'intermediate'),

-- ---------- cloud/bigquery/advanced ----------
('cloud', 'bigquery', 'advanced', 'What problem does BigQuery Omni solve?', '["It provides a faster on-demand pricing tier for BigQuery-native tables", "It lets you query data that physically lives in another cloud (e.g. AWS S3 or Azure Blob Storage) without first copying/moving that data into GCP, using BigQuery''s regular SQL interface", "It automatically migrates all AWS Redshift tables into native BigQuery tables", "It is a caching layer that speeds up repeated queries on the same table"]', 1, 'Omni''s value proposition is querying data where it already lives across clouds, avoiding the cost and latency of a full data migration just to run analytical SQL against it.', 'advanced'),
('cloud', 'bigquery', 'advanced', 'Why would a team set up custom quotas limiting bytes scanned per user/project per day in BigQuery?', '["Quotas are required before BigQuery can be used at all", "To prevent a single runaway or poorly written query (e.g. an accidental full-table scan without a partition filter) from generating an unexpectedly large bill, since on-demand pricing is based directly on bytes scanned", "Quotas control which SQL functions a user is allowed to call", "Quotas are purely for compliance/audit logging, with no cost impact"]', 1, 'Because cost scales directly with bytes scanned under on-demand pricing, a custom quota is a practical guardrail against one bad query or misconfigured job blowing past an expected budget.', 'intermediate'),
('cloud', 'bigquery', 'advanced', 'What is the purpose of querying INFORMATION_SCHEMA.JOBS_BY_PROJECT?', '["It lists scheduled cron jobs configured outside of BigQuery", "It exposes metadata about BigQuery query jobs that have run in the project -- including bytes processed, user, and timing -- which is commonly used to build cost/usage analysis and monitoring queries", "It is used exclusively to cancel currently running jobs", "It only shows jobs from the last hour and cannot query historical jobs"]', 1, 'JOBS_BY_PROJECT (and related INFORMATION_SCHEMA views) is BigQuery''s built-in mechanism for introspecting job history, which is exactly what a cost-monitoring or anomaly-detection query would query against.', 'advanced'),
('cloud', 'bigquery', 'advanced', 'When would a materialized view be a better choice than a regular view for a BigQuery workload?', '["Materialized views should always be preferred over regular views with no tradeoffs", "When the same expensive aggregation query runs repeatedly against a large, relatively slow-changing table -- a materialized view pre-computes and caches the result, serving subsequent matching queries from the cache instead of recomputing from raw data each time", "Materialized views are required before a table can be partitioned", "Materialized views cannot aggregate data, only filter it"]', 1, 'Materialized views trade some storage and refresh overhead for avoiding repeated recomputation of an expensive aggregation, which is valuable specifically when the same costly query pattern runs often against large tables.', 'advanced'),
('cloud', 'bigquery', 'advanced', 'What does BigQuery''s reservations (flat-rate) pricing model change compared to on-demand pricing?', '["Reservations eliminate the need to write SQL queries", "Instead of paying per TB of bytes scanned per query, you commit to a fixed pool of query-processing capacity (slots) for a predictable flat monthly/ongoing cost, which suits high, steady query volume better than unpredictable per-query billing", "Reservations only apply to storage costs, not query costs", "Reservations require migrating all data to a different storage format"]', 1, 'Flat-rate reservations are the alternative billing model to on-demand-per-TB-scanned -- appropriate when query volume is high and predictable enough that a fixed capacity commitment is more cost-effective than per-query billing.', 'advanced'),

-- ---------- cloud/cloud-run/overview ----------
('cloud', 'cloud-run', 'overview', 'What happens to a Cloud Run service''s cost when it receives zero traffic for an extended period?', '["It continues to be billed at a fixed minimum rate regardless of traffic", "With min-instances left at its default of 0, Cloud Run scales the number of running container instances down to zero, and you are not billed for compute time while no instance is running", "Cloud Run services cannot scale below 1 instance under any configuration", "Billing is based on deployment count, not instance runtime, so idle time is irrelevant"]', 1, 'Scale-to-zero is Cloud Run''s core cost proposition -- with min-instances at 0 (the default), no traffic means no running instances means no compute billing, unlike a VM or GKE node pool that keeps running (and billing) regardless of traffic.', 'beginner'),
('cloud', 'cloud-run', 'overview', 'What is a "cold start" in the context of Cloud Run, and when does it happen?', '["It refers to the very first deploy of a service, and never happens again afterward", "It is the added latency a request experiences when Cloud Run has to start a brand-new container instance to handle it, because no warm instance was already running -- most likely right after a scale-to-zero period", "It only happens if the container image is larger than 1GB", "It is a billing term, not a latency phenomenon"]', 1, 'Cold starts are the practical tradeoff for scale-to-zero: the first request after an idle period has to wait for a fresh container to boot before being served, unlike an always-warm instance.', 'beginner'),
('cloud', 'cloud-run', 'overview', 'What does every gcloud run deploy actually create, and why does that matter for rollback?', '["It overwrites the previous deployment in place, so rollback requires redeploying old source code", "It creates a new, immutable revision alongside any existing ones, and only then updates the traffic split to point at it -- because old revisions are never deleted automatically, rolling back is just re-pointing traffic, not a rebuild-and-redeploy", "It deletes all prior revisions to save storage automatically", "Revisions only exist for Cloud Run Jobs, not for Cloud Run Services"]', 1, 'This immutable-revision model is what makes Cloud Run rollback fast and safe -- you are never rebuilding old code, just changing which existing revision receives traffic.', 'intermediate'),
('cloud', 'cloud-run', 'overview', 'How does Cloud Run''s default request concurrency setting affect how a single container instance handles traffic?', '["Each container instance can only ever handle exactly one request at a time, no matter the concurrency setting", "By default a single running container instance can handle multiple concurrent requests (not one request per container) up to the configured concurrency limit, meaning fewer instances may be needed under load than a one-request-per-container model would require", "Concurrency only applies to Cloud Run Jobs, never to Services", "Increasing concurrency always improves latency regardless of the workload''s CPU profile"]', 1, 'Cloud Run''s concurrency model lets one instance serve multiple simultaneous requests, which is why tuning concurrency (higher for I/O-bound, lower for CPU-bound workloads) is a real, workload-dependent decision.', 'intermediate'),
('cloud', 'cloud-run', 'overview', 'When would Cloud Run Jobs be the right tool instead of a Cloud Run Service?', '["Cloud Run Jobs are simply an older, deprecated name for Cloud Run Services", "For tasks that need to run to completion and then stop -- like a database migration, batch data processing, or a scheduled report -- rather than continuously serving HTTP requests, which is what Services are designed for", "Jobs can only be triggered manually and can never be scheduled", "Jobs cannot use container images, only Services can"]', 1, 'Services are built around handling ongoing HTTP request traffic; Jobs are built around run-to-completion, non-HTTP-triggered execution, which fits batch/cron-style workloads far better.', 'beginner'),

-- ---------- cloud/cloud-run/fundamentals ----------
('cloud', 'cloud-run', 'fundamentals', 'What is the effect of deploying with the --no-traffic flag, followed later by gcloud run services update-traffic --to-tags?', '["--no-traffic deletes the previous revision immediately", "The new revision is created and deployed but receives 0% of live traffic until update-traffic explicitly routes a percentage to it -- this is exactly the mechanism a canary/blue-green rollout is built on", "--no-traffic prevents the revision from ever being reachable, even by direct URL", "update-traffic can only be used to send 100% of traffic at once, not partial percentages"]', 1, 'This two-step pattern (deploy quietly, then shift traffic deliberately) is how Cloud Run supports canary releases -- you can validate the new revision under a small percentage of real traffic before promoting it.', 'intermediate'),
('cloud', 'cloud-run', 'fundamentals', 'What is the fastest way to roll back a Cloud Run service to a previously working revision?', '["Redeploy the old source code or container image from scratch", "Run gcloud run services update-traffic with --to-revisions pointing at the old revision''s name, since that revision still exists and is still deployable -- no rebuild required", "Delete the service and recreate it entirely", "Cloud Run has no rollback mechanism; you must contact Google support"]', 1, 'Because revisions are immutable and not deleted automatically, "rollback" is simply repointing the traffic split back to an existing older revision -- a traffic-routing change, not a redeploy.', 'beginner'),
('cloud', 'cloud-run', 'fundamentals', 'What is the difference between Cloud Run Jobs'' --tasks flag and --max-retries flag?', '["They control the exact same thing under two different names", "--tasks controls how many parallel task instances the job runs (e.g. splitting a batch across workers); --max-retries controls how many times a single failed task is retried before being considered failed", "--tasks sets a time limit, --max-retries sets a memory limit", "Neither flag has any effect on Cloud Run Jobs execution"]', 1, '--tasks defines the degree of parallelism across the job''s work; --max-retries is a per-task failure-handling setting, and the two are independent, complementary controls.', 'intermediate'),
('cloud', 'cloud-run', 'fundamentals', 'How does Cloud Scheduler trigger a Cloud Run Job on a schedule?', '["Cloud Scheduler runs the container image directly itself, bypassing Cloud Run entirely", "Cloud Scheduler makes an authenticated HTTP call to the Cloud Run Jobs API''s :run endpoint for the specific job, using an OAuth service-account identity, which then starts an execution of that job", "Jobs cannot be scheduled; only manual gcloud run jobs execute is supported", "Cloud Scheduler and Cloud Run Jobs are mutually incompatible services"]', 1, 'The scheduled-job pattern is Cloud Scheduler calling the Cloud Run Jobs REST API with an authenticated identity, which triggers a normal job execution -- effectively cron-as-a-service on top of Cloud Run Jobs.', 'advanced'),
('cloud', 'cloud-run', 'fundamentals', 'Why is deploying with --source . often simpler than deploying with a hand-written Dockerfile and --image?', '["--source . skips containerization entirely and runs code directly on a VM", "--source . lets Cloud Build automatically detect the language/runtime and build a container image for you (via buildpacks or similar), removing the need to hand-write and maintain a Dockerfile for straightforward apps", "--image and --source produce functionally different deployment targets that are not interchangeable", "--source . is deprecated in favor of --image and should not be used"]', 1, 'For straightforward applications in supported languages, --source . offloads the container-build step to Cloud Build''s automatic buildpack detection, avoiding Dockerfile maintenance entirely.', 'beginner'),

-- ---------- cloud/cloud-run/intermediate ----------
('cloud', 'cloud-run', 'intermediate', 'When gradually shifting traffic to a new revision with --to-revisions=$NEW_REV=10, what happens to the remaining 90%?', '["The remaining 90% of requests are rejected with an error", "The remaining traffic continues to be served by whichever revision(s) were previously receiving it -- a partial traffic split explicitly divides traffic between the specified revisions, it does not imply the rest goes nowhere", "The old revision is automatically deleted once any percentage shifts away from it", "90% is an invalid value and the command would fail"]', 1, 'Traffic splits are explicit: specifying 10% to a new revision as part of a full split (e.g. old=90,new=10) or via incremental commands still leaves the remainder correctly routed to existing revisions.', 'intermediate'),
('cloud', 'cloud-run', 'intermediate', 'What is the main use case for --task-timeout on a Cloud Run Job, and how is it different from a Service''s request timeout?', '["They control the identical concept, just with different flag names for Jobs vs Services", "--task-timeout bounds how long a single task within a run-to-completion Job is allowed to execute (e.g. 1h for a long batch task), whereas a Service''s timeout bounds how long a single HTTP request is allowed to take before being cut off", "--task-timeout has no effect unless --tasks is also set to 1", "Task timeouts apply only to Cloud Scheduler-triggered jobs, not manually executed ones"]', 1, 'Jobs and Services have conceptually different timeout needs -- a Job task is a long-running unit of batch work that may legitimately run far longer than any single HTTP request should be allowed to.', 'intermediate'),
('cloud', 'cloud-run', 'intermediate', 'Why might a team deploy from source with buildpacks (--source .) rather than maintaining Dockerfiles across many small services?', '["Buildpacks produce smaller container images than any hand-written Dockerfile always", "For services in commonly supported languages, buildpacks remove the maintenance burden of writing/updating a Dockerfile per service, letting Cloud Build auto-detect the language and produce a working container image", "Dockerfiles are not supported at all by Cloud Run and never have been", "Buildpacks are required for Cloud Run Jobs but optional for Services"]', 1, 'The buildpacks path trades some control over the exact image contents for significantly less per-service boilerplate -- a reasonable tradeoff for a fleet of straightforward services in supported languages.', 'beginner'),
('cloud', 'cloud-run', 'intermediate', 'What is the purpose of checking gcloud run services describe myapp --format=''yaml(spec.traffic)'' during a canary rollout?', '["It shows the container''s CPU and memory utilization in real time", "It shows the CURRENT traffic split across revisions -- which revision(s) are receiving what percentage -- letting you confirm a canary shift actually took effect as intended before deciding to promote or roll back", "It triggers an automatic rollback if any revision is unhealthy", "It only works after a service has been fully promoted to 100% traffic"]', 1, 'Inspecting spec.traffic is how you verify the actual, current state of a traffic split -- a necessary check during any staged rollout to confirm the intended percentages are really in effect.', 'intermediate'),
('cloud', 'cloud-run', 'intermediate', 'What does gcloud run deploy --source . build with, when no Dockerfile is present in the source directory?', '["It fails immediately, since a Dockerfile is always mandatory", "It uses Google Cloud Buildpacks to detect the language/runtime automatically and build a container image without requiring a Dockerfile", "It deploys the raw source code without containerizing it at all", "It defaults to a generic Ubuntu image regardless of the application language"]', 1, 'Buildpacks are specifically designed to detect language and dependencies and produce a working container image without a hand-written Dockerfile, for supported languages/runtimes.', 'beginner'),

-- ---------- cloud/cloud-run/advanced ----------
('cloud', 'cloud-run', 'advanced', 'What is the difference between the traditional Serverless VPC Access connector and Direct VPC egress for reaching private VPC resources from Cloud Run?', '["They are identical features with two different names introduced for marketing reasons", "The VPC Access connector is a separate managed resource (with its own throughput settings) that Cloud Run traffic routes through; Direct VPC egress is a newer approach that connects Cloud Run directly to the VPC/subnet without provisioning a separate connector resource", "Direct VPC egress only works for Cloud Run Jobs, never Services", "The VPC connector approach has been fully removed and no longer works"]', 1, 'Direct VPC egress is the newer, connector-less approach to reaching private VPC resources, while the Serverless VPC Access connector remains the older, still-supported mechanism requiring its own dedicated subnet and resource.', 'advanced'),
('cloud', 'cloud-run', 'advanced', 'Why would a latency-sensitive Cloud Run service use --cpu-throttling false together with --min-instances greater than 0?', '["These flags have no relationship to latency and only affect billing line items", "By default CPU is throttled/deallocated between requests when an instance has no active request; disabling throttling combined with keeping instances warm (min-instances) eliminates cold-start-driven latency spikes, at the cost of being billed for CPU even during idle time on those warm instances", "cpu-throttling only affects Cloud Run Jobs, not Services", "min-instances greater than 0 is only meaningful when concurrency is set to 1"]', 1, 'Together these settings buy consistently low latency by keeping instances warm and fully CPU-available at all times, trading away some of Cloud Run''s scale-to-zero cost savings for predictable performance.', 'advanced'),
('cloud', 'cloud-run', 'advanced', 'When tuning concurrency for a CPU-bound workload versus an I/O-bound workload on Cloud Run, why does the recommended setting differ?', '["Concurrency has no meaningful effect on either workload type", "A CPU-bound request occupies the CPU for the whole time it is processing, so high concurrency on one instance would starve simultaneous requests of CPU; an I/O-bound request spends most of its time waiting (e.g. on a database), so many can share one instance''s CPU without contention -- hence low concurrency for CPU-bound, high for I/O-bound", "CPU-bound workloads should always use concurrency of exactly 1000", "I/O-bound workloads cannot use concurrency values above 1"]', 1, 'The right concurrency setting depends on what the request spends its time doing -- CPU-bound work genuinely contends for the same CPU allocation, while I/O-bound work leaves CPU free for other concurrent requests while waiting.', 'advanced'),
('cloud', 'cloud-run', 'advanced', 'What does granting roles/run.invoker to a calling service''s service account accomplish in a service-to-service authenticated call pattern?', '["It gives the caller full administrative control over the target Cloud Run service, including the ability to delete it", "It grants the caller service account permission to invoke (send authenticated requests to) the target Cloud Run service, which combined with --no-allow-unauthenticated on the target enforces that only explicitly authorized callers can reach it", "It is unrelated to Cloud Run and only applies to Compute Engine instances", "It automatically encrypts traffic between the two services, which would otherwise be unencrypted"]', 1, 'roles/run.invoker is specifically the permission to call a Cloud Run service -- pairing it with a private (--no-allow-unauthenticated) target service is the standard pattern for locking down internal service-to-service calls.', 'advanced'),
('cloud', 'cloud-run', 'advanced', 'Why might a team choose min-instances=1 on a service instead of min-instances=0, despite the added always-on cost?', '["min-instances only affects Cloud Run Jobs, never Services, so this choice would have no effect", "Keeping at least one instance warm avoids paying the cold-start latency penalty on every request after an idle period, which matters for latency-sensitive user-facing traffic even though it forgoes true scale-to-zero cost savings", "min-instances=1 is required before traffic splitting can be used at all", "There is no meaningful tradeoff; min-instances=1 is strictly better in every scenario"]', 1, 'This is a direct cost-vs-latency tradeoff: min-instances=0 maximizes cost savings but accepts cold starts; min-instances greater than or equal to 1 accepts ongoing cost to guarantee at least one warm instance is always ready.', 'intermediate')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
